// Parity: engines/insight.js vs revive_ml.insight (tests/golden/insight_cases.json, generated by tools/make_golden.py).
import { test } from "node:test";
import assert from "node:assert/strict";
import { golden, assets, close, bundleFromGolden } from "./helpers.mjs";
import { assess } from "../assets/js/engines/pipeline.js";
import { insightFor, breakEven, assign, reroute } from "../assets/js/engines/insight.js";

const cases = golden("insight_cases.json");
const pipe = golden("pipeline_cases.json");

for (const name of Object.keys(pipe)) {
  test(`insight parity: ${name}`, async () => {
    const A = await assets();
    const ref = cases[name].insight;
    const b = await bundleFromGolden(pipe[name].bundle);
    const r = assess(b, A);
    const got = insightFor(r, A.configs, { nRows: cases[name].n_rows });
    assert.deepEqual(got.reasons.all.map((x) => [x.stage, x.tone, x.title, x.metric, x.impact]),
      ref.reasons.all.map((x) => [x.stage, x.tone, x.title, x.metric, x.impact]), "reasons");
    assert.equal(got.confidence.level, ref.confidence.level);
    close(got.confidence.score_0_100, ref.confidence.score_0_100, "confidence", 1e-6, 0.11);
    assert.deepEqual(got.next_actions.map((a) => a.action), ref.next_actions.map((a) => a.action), "next actions");
    assert.equal(got.rule_gap.agrees, ref.rule_gap.agrees);
    assert.equal(got.rule_gap.existing_rule, ref.rule_gap.existing_rule);
    if (ref.robustness) {
      close(got.robustness.share_same_decision, ref.robustness.share_same_decision, "robustness share");
      assert.deepEqual(got.robustness.flips.map((f) => [f.lever, f.value, f.decision]), ref.robustness.flips.map((f) => [f.lever, f.value, f.decision]));
      close(got.robustness.break_even_tariff, ref.robustness.break_even_tariff, "break-even tariff", 1e-6, 1e-6);
    } else assert.equal(got.robustness, null);
    const be = breakEven(r, A.configs, "metal_mult");
    if (ref.break_even_metal) close(be.value, ref.break_even_metal.value, "break-even metal", 1e-6, 1e-6);
    else assert.equal(be, null);
  });
}

test("what-if: the tariff break-even of the clean packs flips the decision (0.06-0.08 USD/kWh)", async () => {
  const A = await assets();
  for (const name of ["clean_lfp", "clean_nmc"]) {
    const r = assess(await bundleFromGolden(pipe[name].bundle), A);
    const be = breakEven(r, A.configs, "tariff");
    assert.ok(be.value > 0.06 && be.value < 0.08, `${name}: ${be.value}`);
    assert.notEqual(reroute(r, A.configs, { tariff: be.value - 0.002 }).decision.split(":")[0], reroute(r, A.configs, { tariff: be.value + 0.002 }).decision.split(":")[0]);
  }
});

test("fleet assignment: same plan and value as Python, limits respected", () => {
  const { packs, limits, result } = cases._assign;
  const got = assign(packs, limits);
  assert.deepEqual(got.plan, result.plan);
  close(got.total_value, result.total_value, "total");
  close(got.value_gap_vs_per_pack_greedy, result.value_gap_vs_per_pack_greedy, "gap");
  for (const [a, u] of Object.entries(got.by_application)) {
    assert.ok(u.packs <= limits[a].packs);
    if ("kwh" in limits[a]) assert.ok(u.kwh <= limits[a].kwh + 1e-9);
  }
});
